        work: {"eyebrow": "Selected projects", "title": "Work &\nprojects.", "cta": "View all projects", "cta_aria": "View all projects", "project1": {"aria": "View Cultivora Land", "img": {"alt": "Cultivora Land - The Garden of Knowledge"}, "category": "Education & Knowledge", "name": "Cultivora Land", "desc": "The Garden of Knowledge - a platform to\nmake learning inspiring and accessible."}, "project2": {"aria": "View T3W", "img": {"alt": "T3W - The 3 Words, a learning platform"}, "category": "Education & Learning", "name": "T3W", "desc": "The 3 Words - a learning platform\ndesigned to focus on the essentials and progress efficiently."}, "project3": {"aria": "View The DSK Journal", "img": {"alt": "The DSK Journal - a notebook of reflections"}, "category": "Blog & Reflections", "name": "The DSK Journal", "desc": "A writing space to share ideas,\nobserve and reflect on the world."}, "project4": {"aria": "View VIGO Services", "img": {"alt": "VIGO Services - professional institutional website"}, "category": "Institutional Website", "name": "VIGO Services", "desc": "Professional institutional website for an\nadministrative services company - clear and reassuring."}, "project5": {"aria": "View Arie's Accessoires", "img": {"alt": "Arie's Accessoires - premium e-commerce website"}, "category": "E-commerce Website", "name": "Arie's Accessoires", "desc": "Premium online accessories boutique, with an\nelegant design built to convert and delight."}, "project6": {"aria": "View Eliano Shoes", "img": {"alt": "Eliano Shoes - premium website for a shoe brand"}, "category": "Brand Website", "name": "Eliano Shoes", "desc": "Premium website for a leather shoe brand,\nwith a bold, carefully crafted identity."}},
