        work: {"eyebrow": "Proyectos realizados", "title": "Creaciones &\nproyectos.", "cta": "Ver todos los proyectos", "cta_aria": "Ver todos los proyectos", "project1": {"aria": "Ver Cultivora Land", "img": {"alt": "Cultivora Land - El Jardín del Saber"}, "category": "Educación & Conocimiento", "name": "Cultivora Land", "desc": "El Jardín del Saber - una plataforma para\nhacer el aprendizaje inspirador y accesible."}, "project2": {"aria": "Ver T3W", "img": {"alt": "T3W - The 3 Words, plataforma de aprendizaje"}, "category": "Educación & Aprendizaje", "name": "T3W", "desc": "The 3 Words - una plataforma de aprendizaje\npensada para ir a lo esencial y progresar con eficacia."}, "project3": {"aria": "Ver The DSK Journal", "img": {"alt": "The DSK Journal - cuaderno de reflexiones"}, "category": "Blog & Reflexiones", "name": "The DSK Journal", "desc": "Un espacio de escritura para compartir ideas,\nobservar y reflexionar sobre el mundo."}, "project4": {"aria": "Ver VIGO Services", "img": {"alt": "VIGO Services - sitio institucional profesional"}, "category": "Sitio institucional", "name": "VIGO Services", "desc": "Sitio institucional profesional para una empresa\nde servicios administrativos, claro y confiable."}, "project5": {"aria": "Ver Arie's Accessoires", "img": {"alt": "Arie's Accessoires - sitio e-commerce premium"}, "category": "Sitio e-commerce", "name": "Arie's Accessoires", "desc": "Tienda en línea de accesorios, con un diseño\npremium pensado para convertir y seducir."}, "project6": {"aria": "Ver Eliano Shoes", "img": {"alt": "Eliano Shoes - sitio premium para marca de zapatos"}, "category": "Sitio de marca", "name": "Eliano Shoes", "desc": "Sitio premium para una marca de zapatos de\ncuero, con una identidad fuerte y cuidada."}},
        blog: {
          eyebrow: "Escritos & reflexiones",
          title: "El\ndiario.",
          cta: "Todos los artículos",
          cta_aria: "Ver todos los artículos",
          readmore: "Leer más",
          post1: { aria: "Leer: Por qué aprendo a programar solo",                   tag: "Desarrollo",          img: { alt: "Pantalla de ordenador mostrando código" },           category: "Desarrollo",          date: "8 de marzo de 2025", title: "Por qué aprendo a programar solo - y lo que eso me enseñó sobre mí",    excerpt: "Aprender desarrollo web sin escuela ni mentor es una aventura tan técnica como humana. Esto es lo que el camino me ha enseñado.", pullquote: "El código obedece al instante.\nEntender por qué toma más tiempo." },
          post2: { aria: "Leer: La educación como herramienta de transformación social", tag: "Educación",      img: { alt: "Libros y cuadernos abiertos sobre un escritorio" },  category: "Educación",           date: "21 feb. 2025",       title: "La educación como herramienta de transformación social",              excerpt: "Creo que aprender puede cambiar una sociedad. Aquí explico por qué dedico parte de mi energía a hacer el conocimiento más accesible y vivo.", pullquote: "El diploma abre una puerta.\nEl saber, en cambio, ilumina el camino." },
          post3: { aria: "Leer: El fracaso como maestro",                              tag: "Desarrollo personal", img: { alt: "Escritorio con cuaderno y bolígrafo abierto" },   category: "Desarrollo personal", date: "14 ene. 2025",       title: "El fracaso como maestro - reflexiones sobre el progreso",             excerpt: "Cada error contiene una lección. Así aprendí a ver mis dificultades no como obstáculos, sino como etapas.", pullquote: "El fracaso cierra una puerta.\nAbre otra, más honesta." }
        },
